{
  "name": "@potb/opencode-plugin-noop",
  "version": "0.0.2",
  "description": "The simplest possible OpenCode plugin: a no-op POC / scaffold.",
  "keywords": [
    "ai",
    "opencode",
    "opencode-plugin",
    "plugin"
  ],
  "homepage": "https://github.com/potb/opencode-plugins/tree/main/packages/opencode-plugin-noop#readme",
  "bugs": {
    "url": "https://github.com/potb/opencode-plugins/issues"
  },
  "license": "MIT",
  "author": "Peïo Thibault",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/potb/opencode-plugins.git",
    "directory": "packages/opencode-plugin-noop"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "type": "module",
  "main": "./dist/index.js",
  "module": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "publishConfig": {
    "access": "public"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.0.0"
  },
  "scripts": {
    "build": "tsc -p tsconfig.build.json",
    "typecheck": "tsgo --noEmit",
    "test": "bun test",
    "clean": "rm -rf dist"
  }
}
